// validateScannerCapabilities checks that an unprivileged process can use the
// packet capabilities needed by nmap's privileged scan techniques.
func validateScannerCapabilities(path string) error {
	output, err := exec.Command("getcap", path).Output()
	if err != nil {
		return fmt.Errorf("portscan.scannerBinPath %q: failed to check capabilities: %w", path, err)
	}
	return parseScannerCapabilities(path, string(output))
}

func parseScannerCapabilities(path, output string) error {
	capabilities := strings.TrimSpace(string(output))
	if capabilities == "" {
		return fmt.Errorf("portscan.scannerBinPath %q has no file capabilities", path)
	}
	if strings.ContainsAny(capabilities, "\r\n") || !strings.HasPrefix(capabilities, path) {
		return fmt.Errorf("portscan.scannerBinPath %q has malformed capability data: %q", path, capabilities)
	}
	capabilities = strings.TrimSpace(strings.TrimPrefix(capabilities, path))
	capabilities = strings.TrimSpace(strings.TrimPrefix(capabilities, "="))
	separator := strings.IndexAny(capabilities, "=+")
	if separator <= 0 || separator == len(capabilities)-1 {
		return fmt.Errorf("portscan.scannerBinPath %q has malformed capability data: %q", path, string(output))
	}
	flags := strings.TrimSpace(capabilities[separator+1:])
	for _, flag := range flags {
		if !strings.ContainsRune("eip", flag) {
			return fmt.Errorf("portscan.scannerBinPath %q has malformed capability data: %q", path, output)
		}
	}
	if !strings.Contains(flags, "e") || !strings.Contains(flags, "p") {
		return fmt.Errorf("portscan.scannerBinPath %q needs effective and permitted capabilities", path)
	}
	configured := make(map[string]bool)
	for _, capability := range strings.Split(capabilities[:separator], ",") {
		name := strings.TrimSpace(capability)
		if !strings.HasPrefix(name, "cap_") || len(name) == len("cap_") ||
			strings.IndexFunc(name[len("cap_"):], func(r rune) bool {
				return !(r >= 'a' && r <= 'z' || r >= '0' && r <= '9' || r == '_')
			}) >= 0 {
			return fmt.Errorf("portscan.scannerBinPath %q has malformed capability data: %q", path, string(output))
		}
		configured[name] = true
	}
	for _, required := range []string{"cap_net_raw", "cap_net_admin"} {
		if !configured[required] {
			return fmt.Errorf("portscan.scannerBinPath %q is missing %s capability", path, required)
		}
	}
	return nil
}
	}
	for _, conf := range []PortScanConf{
		{ScannerBinPath: "/usr/bin/nmap"},
		{ScanTechniques: []string{"sT"}},
		{SourcePort: "443"},
		{HasPrivileged: true},
	} {
		if conf.IsZero() {
			t.Errorf("IsZero returned true for %+v", conf)
		}
	}
}

func TestPortScanConfValidate(t *testing.T) {
	scannerPath := filepath.Join(t.TempDir(), "nmap")
	if err := os.WriteFile(scannerPath, []byte("#!/bin/sh\nexit 0\n"), 0755); err != nil {
		t.Fatal(err)
	}

	tests := []struct {
		name string
		conf PortScanConf
		want string
	}{
		{"connect", PortScanConf{ScannerBinPath: scannerPath, ScanTechniques: []string{"sT"}}, ""},
		{"default connect", PortScanConf{ScannerBinPath: scannerPath}, ""},
		{"missing path", PortScanConf{ScanTechniques: []string{"sT"}}, "scannerBinPath is required"},
		{"blank path", PortScanConf{ScannerBinPath: " ", ScanTechniques: []string{"sT"}}, "scannerBinPath is required"},
		{"nonexistent path", PortScanConf{ScannerBinPath: filepath.Join(t.TempDir(), "missing"), ScanTechniques: []string{"sT"}}, "scannerBinPath"},
		{"unsupported", PortScanConf{ScannerBinPath: scannerPath, ScanTechniques: []string{"sZ"}}, "unsupported"},
		{"multiple", PortScanConf{ScannerBinPath: scannerPath, ScanTechniques: []string{"sT", "sT"}}, "multiple scan techniques"},
		{"privilege", PortScanConf{ScannerBinPath: scannerPath, ScanTechniques: []string{"sS"}}, "requires hasPrivileged"},
		{"connect source port", PortScanConf{ScannerBinPath: scannerPath, ScanTechniques: []string{"sT"}, SourcePort: "443"}, "cannot be used"},
		{"default connect source port", PortScanConf{ScannerBinPath: scannerPath, SourcePort: "443"}, "cannot be used"},
		{"zero source port", PortScanConf{ScannerBinPath: scannerPath, SourcePort: "0"}, "0 is reserved"},
		{"negative source port", PortScanConf{ScannerBinPath: scannerPath, SourcePort: "-1"}, "integer in [0, 65535]"},
		{"too large source port", PortScanConf{ScannerBinPath: scannerPath, SourcePort: "65536"}, "integer in [0, 65535]"},
		{"noninteger source port", PortScanConf{ScannerBinPath: scannerPath, SourcePort: "port"}, "integer in [0, 65535]"},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			errs := tt.conf.Validate()
			if tt.want == "" {
				if len(errs) != 0 {
					t.Fatalf("Validate() = %v, want no errors", errs)
				}
				return
			}
			for _, err := range errs {
				if strings.Contains(err.Error(), tt.want) {
					return
				}
			}
			t.Errorf("Validate() = %v, want error containing %q", errs, tt.want)
		})
	}
}

